Elab.command: Lean.Parser.Command.definition: ✅️ def Impl.insert : Val :=
  hl_val%
    λ node nval,
      let lk := fst(node);
        &acquire (lk);
          let ptr := snd(node);
            let contents := !ptr;
              let val := fst(contents);
                let next := snd(contents);
                  -- create a new node with the new value and the old next pointer
                  let nlk := &newlock #();
                    let nptr := ref((nval, next));
                      let nnode := (nlk, nptr);
                        let ncontents := (val, some(nnode)); ptr ← ncontents; &release (lk); nnode

